  out.config = await Developer.shell({ command: "find ~/.agnes -maxdepth 3 -name 'config.yaml*' 2>/dev/null; echo '---'; find /Users/billtse/.agnes/temporary/2026-10-12 -maxdepth 4 -name 'config.yaml*' 2>/dev/null", timeout_secs: 10 });
  return out;
}

